# ORACLE_VECTORS_END

doAssert wideningVectors.len == 4096
doAssert narrowingVectors.len == 4096

for vector in wideningVectors:
  let
    source =
      binary128.fromBits(
        vector.sourceHigh,
        vector.sourceLow,
      )

    widened =
      binary256.toFloat256(
        source
      )

    widenedBits =
      binary256.toBits(
        widened
      )

  doAssert widenedBits.word3 == vector.expectedWord3

  doAssert widenedBits.word2 == vector.expectedWord2

  doAssert widenedBits.word1 == vector.expectedWord1

  doAssert widenedBits.word0 == vector.expectedWord0

  let
    roundTrip =
      binary256.toFloat128(
        widened
      )

    roundTripBits =
      binary128.toBits(
        roundTrip
      )

  doAssert roundTripBits.high == vector.sourceHigh

  doAssert roundTripBits.low == vector.sourceLow

for vector in narrowingVectors:
  let
    source =
      binary256.fromBits(
        vector.sourceWord3,
        vector.sourceWord2,
        vector.sourceWord1,
        vector.sourceWord0,
      )

    narrowed =
      binary256.toFloat128(
        source
      )

    narrowedBits =
      binary128.toBits(
        narrowed
      )

  doAssert narrowedBits.high == vector.expectedHigh

  doAssert narrowedBits.low == vector.expectedLow

echo "F256_FLOAT128_INTEROP_CONTRACT_OK\t4096\t4096\t4096\t12288\t51"
